package main

import (
	"encoding/base64"
	"sort"
)

// Accounts defines a key/value for user/pass list of authorized logins.
type Accounts map[string]string

type authPair struct {
	value string
	user  string
}

type authPairs []authPair

// searchCredential looks up a credential string in the sorted table.
// It returns the owning user and true on a hit, "" and false otherwise.
func (a authPairs) searchCredential(authValue string) (string, bool) {
	if authValue == "" {
		return "", false
	}
	i := sort.Search(len(a), func(i int) bool { return a[i].value > authValue })
	if i < len(a) && a[i].value == authValue {
		return a[i].user, true
	}
	return "", false
}

func authorizationHeader(user, password string) string {
	base := user + ":" + password
	return "Basic " + base64.StdEncoding.EncodeToString([]byte(base))
}

// processAccounts compiles the account table into a credential list ordered
// by credential value so that it can be searched with a binary lookup.
func processAccounts(accounts Accounts) authPairs {
	length := len(accounts)
	pairs := make(authPairs, 0, length)
	for user, password := range accounts {
		if user == "" {
			panic("User can not be empty")
		}
		pairs = append(pairs, authPair{
			value: authorizationHeader(user, password),
			user:  user,
		})
	}
	sort.Slice(pairs, func(i, j int) bool { return pairs[i].value < pairs[j].value })
	return pairs
}

