package main

import (
    "fmt"
    "os"
)

var pass, fail int

func check(name string, ok bool) {
    if ok {
        pass++
    } else {
        fail++
        fmt.Fprintln(os.Stderr, "FAIL", name)
    }
}

func main() {
    check("header", authorizationHeader("demo", "secret") == "Basic ZGVtbzpzZWNyZXQ=")
    accounts := Accounts{"demo": "secret", "kai": "tok3n", "zoe": "pass"}
    pairs := processAccounts(accounts)
    check("len", len(pairs) == len(accounts))
    sorted := true
    for i := 1; i < len(pairs); i++ {
        if pairs[i].value < pairs[i-1].value {
            sorted = false
        }
    }
    check("sorted", sorted)
    seen := map[string]bool{}
    for _, p := range pairs {
        seen[p.user] = true
        check("value:"+p.user, p.value == authorizationHeader(p.user, accounts[p.user]))
    }
    check("users", len(seen) == len(accounts))
    for user, password := range accounts {
        u, ok := pairs.searchCredential(authorizationHeader(user, password))
        check("hit:"+user, ok && u == user)
    }
    u, ok := pairs.searchCredential("Basic ZGVtbzpzZWNyZXQ=")
    check("hit exact", ok && u == "demo")
    u, ok = pairs.searchCredential("Basic nope")
    check("miss", !ok && u == "")
    u, ok = pairs.searchCredential("")
    check("empty", !ok && u == "")
    empty := processAccounts(Accounts{})
    u, ok = empty.searchCredential("Basic ZGVtbzpzZWNyZXQ=")
    check("empty table miss", !ok && u == "")
    func() {
        defer func() {
            if r := recover(); r != nil {
                pass++
            } else {
                fail++
                fmt.Fprintln(os.Stderr, "FAIL panic")
            }
        }()
        processAccounts(Accounts{"": "x"})
    }()
    fmt.Printf("TESTS %d %d\n", pass, fail)
    if fail > 0 {
        os.Exit(1)
    }
}
